code_examples.code:
.container {
  height: 100vh;
  display: grid;
  gap: 3rem;
  grid-template-columns: 1fr 1fr 1.5fr;
  grid-template-rows: 1fr 1fr;
}

.item {
  font-size: 5rem;
  color: white;
  background-color: blueviolet;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cowboy { grid-column: span 2; }
/* same result using lines */
.cowboy { grid-column-start: 1; grid-column-end: 3; }
.cowboy { grid-column: 1 / 3; }

.cowboy    { background-color: #00b9ff; grid-area: 1 / 1 / 2 / 3; }
.astronaut { background-color: #03989e; grid-area: 2 / 1 / 3 / 3; }
.book      { background-color: #e5833180; grid-area: 1 / 2 / 3 / 4; } /* overlaps both */

solution_code.code:
.item {
  display: flex;
  align-items: center;
  justify-content: center;
}

.cowboy {
  background-color: #00b9ff;
  grid-column: span 2;
}

.astronaut {
  background-color: #03989e;
  grid-area: 2 / 1 / 3 / 3;
}

.book {
  background-color: #e58331;
  grid-area: 1 / 3 / 3 / 4;
  /* or grid-area: 1 / 3 / -1 / -1; or grid-row: span 2; */
}
